const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Report the deploy result from the server (SSH output) to Telegram.
const info = $('Check GitHub for changes').first().json;
const out = String($input.first().json.stdout || $input.first().json.stderr || '');
const failed = /ERROR|error:|failed/i.test(out);
const what = info.stacks.length ? info.stacks.join(', ') : 'repo files only';
const lines = [`${failed ? '⚠️ Deploy finished with problems' : '🚀 Deployed'}: ${what} (${info.head})`];
for (const m of info.messages) lines.push(`• ${m}`);
if (failed) lines.push('', out.split('\n').filter(l => /ERROR|error|fail|skip/i.test(l)).slice(-6).join('\n') || out.slice(-600));
await say(lines.join('\n'));
return [{ json: { reported: true } }];
